/**
 * DREVAIA OS
 * Canonical AI Provider Contract
 */

export interface ProviderGenerationRequest {

  /**
   * Optional system prompt.
   */
  system?: string;

  /**
   * User prompt.
   */
  prompt: string;

  /**
   * Optional model.
   */
  model?: string;

  /**
   * Temperature.
   */
  temperature?: number;

  /**
   * Maximum output tokens.
   */
  maxTokens?: number;

}

export interface ProviderUsage {

  /**
   * Number of tokens sent to the provider.
   */
  promptTokens?: number;

  /**
   * Number of tokens generated by the provider.
   */
  completionTokens?: number;

  /**
   * Total tokens used by the generation.
   */
  totalTokens?: number;

}

export interface ProviderGenerationResponse {

  /**
   * Generated content.
   */
  content: string;

  /**
   * Model used by the provider.
   */
  model: string;

  /**
   * Provider runtime version.
   */
  version: string;

  /**
   * Usage metrics returned by the provider.
   *
   * Optional because not every AI provider
   * necessarily exposes token usage.
   */
  usage?: ProviderUsage;

}

export interface AIProvider {

  /**
   * Provider identifier.
   */
  readonly id: string;

  /**
   * Provider display name.
   */
  readonly name: string;

  /**
   * Health check.
   */
  health(): Promise<boolean>;

  /**
   * Executes a generation request.
   */
  generate(
    request: ProviderGenerationRequest,
  ): Promise<ProviderGenerationResponse>;

}